-- 4 plain stock WotLK spell ids (Permanent Feign Death (Root), Permanent
-- Feign Death, Generic Quest Invisibility 1, Dual Wield) referenced by
-- creature_addon.auras rows but missing from acore_world.spell_dbc -- this
-- fork's spell_dbc is an incrementally-populated mirror, NOT a full copy of
-- the client's Spell.dbc, so even totally-vanilla spells need an explicit
-- row here if nothing has referenced them before. Unlike 39_ (Cata content),
-- these are raw-copied straight from the live 3.3.5 client's own Spell.dbc
-- (K:/Dark-Chaos/Server/data/dbc/Spell.dbc) -- no remapping needed, same
-- client version. 29266 is shared with Plaguelands/48_ -- duplicated there
-- on purpose so each apply_all.sql stays self-contained.
-- =====================================================================

DELETE FROM `spell_dbc` WHERE `ID` IN (31261,29266,49414,42459);

